inline const uint8_t *deskyExpressionFrame(DeskyExpression expression,
                                           uint8_t frame) {
  frame %= DESKY_ANIMATION_FRAMES;
  switch (expression) {
  case DeskyExpression::HAPPY:
    return deskyHappyFrames[frame];
  case DeskyExpression::LAUGHING:
    return deskyLaughingFrames[frame];
  case DeskyExpression::BIG_GRIN:
    return deskyBigGrinFrames[frame];
  case DeskyExpression::ANGRY:
    return deskyAngryFrames[frame];
  case DeskyExpression::CONFUSED:
    return deskyConfusedFrames[frame];
  case DeskyExpression::CRYING:
    return deskyCryingFrames[frame];
  case DeskyExpression::CURIOUS:
    return deskyCuriousFrames[frame];
  case DeskyExpression::NEUTRAL:
    return deskyNeutralFrames[frame];
  case DeskyExpression::LOOK_LEFT:
    return deskyLookLeftFrames[frame];
  case DeskyExpression::LOOK_RIGHT:
    return deskyLookRightFrames[frame];
  case DeskyExpression::LOVE:
    return deskyLoveFrames[frame];
  case DeskyExpression::SAD:
    return deskySadFrames[frame];
  case DeskyExpression::SHOCKED:
    return deskyShockedFrames[frame];
  case DeskyExpression::SLEEPY:
    return deskySleepyFrames[frame];
  case DeskyExpression::SURPRISED:
    return deskySurprisedFrames[frame];
  case DeskyExpression::WINK:
    return deskyWinkFrames[frame];
  }
  return deskyNeutralFrames[frame];
}

inline void deskyDrawExpression(U8G2 &display, DeskyExpression expression,
                                uint8_t frame) {
  display.clearBuffer();
  display.drawXBMP(0, 0, DESKY_ANIMATION_WIDTH, DESKY_ANIMATION_HEIGHT,
                   deskyExpressionFrame(expression, frame));
  display.sendBuffer();
}

// Nonblocking one-shot player. Call update() repeatedly from loop().
class DeskyAnimation {
public:
  void play(DeskyExpression expression, uint32_t now, uint16_t frameMs = 100) {
    expression_ = expression;
    frame_ = 0;
    frameMs_ = frameMs ? frameMs : 1;
    nextFrameAt_ = now;
    playing_ = true;
  }
  bool update(U8G2 &display, uint32_t now) {
    if (!playing_ || (int32_t)(now - nextFrameAt_) < 0)
      return false;
    deskyDrawExpression(display, expression_, frame_);
    nextFrameAt_ = now + frameMs_;
    if (++frame_ >= DESKY_ANIMATION_FRAMES)
      playing_ = false;
    return true;
  }
  bool isPlaying() const { return playing_; }

private:
  DeskyExpression expression_ = DeskyExpression::NEUTRAL;
  uint8_t frame_ = 0;
  uint16_t frameMs_ = 100;
  uint32_t nextFrameAt_ = 0;
  bool playing_ = false;
};